<?php
declare(strict_types=1);
require_once __DIR__.'/finance_core.php';
require_once __DIR__.'/invoice_lib.php';
require_once __DIR__.'/platform.php';
require_once __DIR__.'/document_storage.php';
function cashAssetsRequire(PDO $pdo):void {if(!(int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='300_cash_assets'")->fetchColumn())throw new RuntimeException('Kasse/Anlagen benötigen Migration v300.');}
function caText(string $value,int $limit,bool $required=true):string {$value=trim($value);if(($required&&$value==='')||!mb_check_encoding($value,'UTF-8')||mb_strlen($value)>$limit||str_contains($value,"\0"))throw new InvalidArgumentException('Textangabe ungültig oder zu lang.');return $value;}
function caRequest(string $key):void {if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new InvalidArgumentException('Anfrageidentität ungültig.');}
function caDate(string $date):void {if(!zgsValidDate($date)||$date>(new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin')))->format('Y-m-d'))throw new InvalidArgumentException('Tatsächliches Datum erforderlich, nicht in der Zukunft.');}
function caBegin(PDO $pdo,int $admin):void {cashAssetsRequire($pdo);if($admin<1)throw new InvalidArgumentException('Inhaber-Anmeldung erforderlich.');if($pdo->inTransaction())throw new RuntimeException('Eigene Transaktion erforderlich.');$pdo->beginTransaction();}
function cashLock(PDO $pdo):array {$q=$pdo->query('SELECT * FROM cash_accounts WHERE id=1 FOR UPDATE');return $q->fetch()?:throw new RuntimeException('Kassenkonto fehlt.');}
function cashInitialize(PDO $pdo,int $admin,string $date,int $cents,string $note):void {
 caDate($date);$note=caText($note,500);if($cents<0||$cents>99999999999)throw new InvalidArgumentException('Gezählter Anfangsbestand 0–999999999,99 EUR.');caBegin($pdo,$admin);
 try{$a=cashLock($pdo);if($a['opening_on']!==null){if($a['opening_on']===$date&&(int)$a['opening_cents']===$cents&&$a['opening_note']===$note){$pdo->commit();return;}throw new RuntimeException('Anfangsbestand gesperrt. Korrekturen nur nachvollziehbar erfassen.');}$pdo->prepare('UPDATE cash_accounts SET opening_on=?,opening_cents=?,opening_note=?,initialized_by=?,initialized_at=UTC_TIMESTAMP() WHERE id=1')->execute([$date,$cents,$note,$admin]);gszAudit($pdo,$admin,'cash_initialized',['account_id'=>1]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
/** Re-evaluate all chronological balances, including a backdated row; never permit negative history. */
function cashCheckTimeline(array $account,array $rows,?array $candidate=null):array {
 if(!$account['opening_on'])throw new RuntimeException('Zuerst den tatsächlich gezählten Anfangsbestand erfassen.');if(count($rows)+($candidate===null?0:1)>10000)throw new RuntimeException('Kassenlimit 10000 Zeilen; Zeitraum-/Archivkonzept prüfen.');
 if($candidate!==null)$rows[]=$candidate;usort($rows,fn($a,$b)=>[$a['occurred_on'],(int)$a['id']]<=>[$b['occurred_on'],(int)$b['id']]);$balance=(int)$account['opening_cents'];if($balance<0)throw new RuntimeException('Negativer Anfangsbestand; Datenintegrität prüfen.');$out=[];
 foreach($rows as $r){caDate($r['occurred_on']);if($r['occurred_on']<$account['opening_on'])throw new RuntimeException('Bewegung liegt vor dem gezählten Anfangsbestand.');$delta=(int)$r['amount_cents'];if(abs($delta)>99999999999||abs($balance)>99999999999999)throw new RuntimeException('Kassenbetragsgrenze überschritten.');$balance+=$delta;if($balance>99999999999999)throw new RuntimeException('Kassenbetragsgrenze überschritten.');if($balance<0)throw new RuntimeException('Negativer Kassenbestand im zeitlichen Verlauf. Keine Buchung gespeichert.');$r['balance_cents']=$balance;$out[]=$r;}return ['balance_cents'=>$balance,'entries'=>$out];
}
function cashData(PDO $pdo):array {cashAssetsRequire($pdo);$a=$pdo->query('SELECT * FROM cash_accounts WHERE id=1')->fetch();if(!$a)throw new RuntimeException('Kassenkonto fehlt.');$rows=$pdo->query('SELECT * FROM cash_entries WHERE account_id=1 ORDER BY occurred_on,id LIMIT 10001')->fetchAll();return ['account'=>$a]+($a['opening_on']?cashCheckTimeline($a,$rows):['balance_cents'=>0,'entries'=>[]]);}
function cashFindRequest(PDO $pdo,string $request,string $kind,string $date,int $amount,?int $payment,?int $reversal,string $description):?int {
 $q=$pdo->prepare('SELECT * FROM cash_entries WHERE request_key=?');$q->execute([$request]);$old=$q->fetch();if(!$old)return null;if($old['kind']!==$kind||$old['occurred_on']!==$date||(int)$old['amount_cents']!==$amount||(int)$old['payment_id']!==(int)$payment||(int)$old['reversal_of']!==(int)$reversal||$old['description']!==$description)throw new RuntimeException('Anfrageidentität mit abweichenden Daten.');return (int)$old['id'];
}
function cashInsertLocked(PDO $pdo,int $admin,array $account,string $kind,string $date,int $amount,string $description,string $request,?int $payment=null,?int $reversal=null):int {
 if($amount===0||abs($amount)>99999999999)throw new InvalidArgumentException('Kassenbetrag ungültig.');$rows=$pdo->query('SELECT * FROM cash_entries WHERE account_id=1 ORDER BY occurred_on,id LIMIT 10001 FOR UPDATE')->fetchAll();cashCheckTimeline($account,$rows,['id'=>PHP_INT_MAX,'occurred_on'=>$date,'amount_cents'=>$amount]);$pdo->prepare('INSERT INTO cash_entries(account_id,occurred_on,kind,amount_cents,description,payment_id,reversal_of,request_key,admin_id) VALUES(1,?,?,?,?,?,?,?,?)')->execute([$date,$kind,$amount,$description,$payment,$reversal,$request,$admin]);$id=(int)$pdo->lastInsertId();gszAudit($pdo,$admin,'cash_entry',['cash_id'=>$id,'kind'=>$kind,'payment_id'=>$payment,'reversal_of'=>$reversal]);return $id;
}
function cashTransfer(PDO $pdo,int $admin,string $kind,string $date,int $amount,string $description,string $request):int {
 caRequest($request);caDate($date);$description=caText($description,500);if(!in_array($kind,['deposit','withdrawal'],true)||$amount<=0||$amount>99999999999)throw new InvalidArgumentException('Einlage/Entnahme mit positivem Betrag erforderlich.');$signed=$kind==='withdrawal'?-$amount:$amount;caBegin($pdo,$admin);
 try{$a=cashLock($pdo);if($id=cashFindRequest($pdo,$request,$kind,$date,$signed,null,null,$description)){$pdo->commit();return $id;}$id=cashInsertLocked($pdo,$admin,$a,$kind,$date,$signed,$description,$request);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
/** Cash register reflects already confirmed payments, not a second financial ledger. */
function cashLinkPayment(PDO $pdo,int $admin,int $payment,string $request,bool $physicalConfirmed):int {
 caRequest($request);if($payment<1||!$physicalConfirmed)throw new InvalidArgumentException('Tatsächlichen Bargeldfluss ausdrücklich bestätigen.');caBegin($pdo,$admin);
 try{$a=cashLock($pdo);$q=$pdo->prepare('SELECT * FROM finance_payments WHERE id=? FOR UPDATE');$q->execute([$payment]);$p=$q->fetch();if(!$p||$p['bank_transaction_id']!==null)throw new RuntimeException('Nur vorhandene Zahlung ohne Bankzuordnung übernehmen.');$date=$p['paid_on'];$amount=(int)$p['amount_cents'];$description='Bestätigte Barzahlung #'.$payment.($p['reversal_of']?' / Gegenzeile zu Zahlung #'.$p['reversal_of']:'');
 if($id=cashFindRequest($pdo,$request,'payment',$date,$amount,$payment,null,$description)){$pdo->commit();return $id;}$q=$pdo->prepare('SELECT id FROM cash_entries WHERE payment_id=?');$q->execute([$payment]);if($id=$q->fetchColumn()){$pdo->commit();return (int)$id;}$id=cashInsertLocked($pdo,$admin,$a,'payment',$date,$amount,$description,$request,$payment);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function cashReverseTransfer(PDO $pdo,int $admin,int $id,string $date,string $reason,string $request):int {
 caRequest($request);caDate($date);$reason=caText($reason,500);caBegin($pdo,$admin);try{$a=cashLock($pdo);$q=$pdo->prepare('SELECT * FROM cash_entries WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old||!in_array($old['kind'],['deposit','withdrawal'],true))throw new RuntimeException('Nur Einlage/Entnahme hier korrigieren. Zahlungen im Zahlungsworkflow korrigieren und Gegenzeile übernehmen.');if($date<$old['occurred_on'])throw new RuntimeException('Korrekturdatum liegt vor Ursprungsbewegung.');$description='Korrektur Kassenzeile #'.$id.': '.$reason;if($duplicate=cashFindRequest($pdo,$request,'correction',$date,-(int)$old['amount_cents'],null,$id,$description)){$pdo->commit();return $duplicate;}$q=$pdo->prepare('SELECT id FROM cash_entries WHERE reversal_of=?');$q->execute([$id]);if($duplicate=$q->fetchColumn()){$pdo->commit();return (int)$duplicate;}$new=cashInsertLocked($pdo,$admin,$a,'correction',$date,-(int)$old['amount_cents'],$description,$request,null,$id);$pdo->commit();return $new;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function cashUnlinkedPayments(PDO $pdo):array {$q=$pdo->query('SELECT p.id,p.paid_on,p.amount_cents,p.receipt_id,p.invoice_id,p.reversal_of FROM finance_payments p LEFT JOIN cash_entries c ON c.payment_id=p.id WHERE c.id IS NULL AND p.bank_transaction_id IS NULL ORDER BY p.paid_on,p.id LIMIT 100');return $q->fetchAll();}
function cashUnlinkedReversals(PDO $pdo):array {return $pdo->query('SELECT r.id,r.paid_on,r.amount_cents,r.reversal_of FROM finance_payments r JOIN cash_entries original ON original.payment_id=r.reversal_of LEFT JOIN cash_entries linked ON linked.payment_id=r.id WHERE linked.id IS NULL ORDER BY r.id LIMIT 100')->fetchAll();}
function cashCsv(array $data):string {$lines=[['Datum','Kassenzeile','Art','Betrag EUR','Bestand EUR','Zahlung-ID','Korrektur-zu','Beschreibung']];$a=$data['account'];if($a['opening_on'])$lines[]=[$a['opening_on'],'','Anfangsbestand',financeDecimal((int)$a['opening_cents']),financeDecimal((int)$a['opening_cents']),'','',$a['opening_note']];foreach($data['entries'] as $r)$lines[]=[$r['occurred_on'],$r['id'],$r['kind'],financeDecimal((int)$r['amount_cents']),financeDecimal((int)$r['balance_cents']),$r['payment_id'],$r['reversal_of'],$r['description']];$out="\xEF\xBB\xBF";foreach($lines as $line)$out.=implode(';',array_map('invCsvCell',$line))."\r\n";return $out;}
function assetFields(array $in):array {
 $name=caText((string)($in['name']??''),190);$date=(string)($in['acquired_on']??'');$service=(string)($in['in_service_on']??'');caDate($date);caDate($service);if($service<$date)throw new InvalidArgumentException('Inbetriebnahme vor Anschaffung fachlich prüfen.');$cost=financeCents((string)($in['acquisition']??''),'de');$residual=financeCents((string)($in['residual']??'0'),'de');$document=filter_var($in['document_id']??'',FILTER_VALIDATE_INT);$property=filter_var($in['property_id']??0,FILTER_VALIDATE_INT);if($cost<=0||$residual<0||$residual>$cost||!$document||$document<1||$property===false||$property<0)throw new InvalidArgumentException('Anschaffungswert/Restwert/Originaldokument prüfen.');return ['name'=>$name,'acquired_on'=>$date,'in_service_on'=>$service,'acquisition_cents'=>$cost,'residual_cents'=>$residual,'document_id'=>$document,'property_id'=>$property?:null,'notes'=>caText((string)($in['notes']??''),5000,false)];
}
function assetLock(PDO $pdo,int $id,?int $version=null):array {$q=$pdo->prepare('SELECT * FROM asset_register WHERE id=? FOR UPDATE');$q->execute([$id]);$a=$q->fetch();if(!$a)throw new RuntimeException('Anlage nicht gefunden.');if($version!==null&&(int)$a['row_version']!==$version)throw new RuntimeException('Anlagenstand inzwischen geändert. Neu laden.');return $a;}
function assetEvent(PDO $pdo,int $admin,int $id,string $action,array $detail=[]):void {$pdo->prepare('INSERT INTO asset_events(asset_id,admin_id,action,detail_json) VALUES(?,?,?,?)')->execute([$id,$admin,$action,json_encode($detail,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);gszAudit($pdo,$admin,'asset_'.$action,['asset_id'=>$id]);}
function assetValidateDocument(PDO $pdo,int $document):void {$q=$pdo->prepare('SELECT * FROM documents WHERE id=?');$q->execute([$document]);$d=$q->fetch();if(!$d||!preg_match('/^[a-f0-9]{32}$/D',$d['stored_name']))throw new RuntimeException('Geschütztes Originaldokument erforderlich.');$file=documentStorageDir().'/'.$d['stored_name'];if(is_link($file)||!is_file($file)||hash_file('sha256',$file)!==$d['sha256'])throw new RuntimeException('Originalintegrität verletzt.');}
function assetSave(PDO $pdo,int $admin,array $in,string $request,int $id=0,?int $version=null):int {
 $data=assetFields($in);caRequest($request);caBegin($pdo,$admin);try{$old=$id?assetLock($pdo,$id,$version):null;if($old&&$old['status']!=='draft')throw new RuntimeException('Geprüfte Anlage gesperrt. Keine stille Änderung.');if($old){$plan=$pdo->prepare('SELECT year,amount_cents FROM asset_plan_rows WHERE asset_id=? ORDER BY year');$plan->execute([$id]);assetSchedule(array_replace($old,$data),$plan->fetchAll());}assetValidateDocument($pdo,$data['document_id']);if($data['property_id']){$q=$pdo->prepare('SELECT id FROM properties WHERE id=?');$q->execute([$data['property_id']]);if(!$q->fetchColumn())throw new RuntimeException('Objekt nicht gefunden.');}
 if($id)$pdo->prepare('UPDATE asset_register SET name=?,acquired_on=?,in_service_on=?,acquisition_cents=?,residual_cents=?,document_id=?,property_id=?,notes=?,row_version=row_version+1 WHERE id=?')->execute([...array_values($data),$id]);else{$q=$pdo->prepare('SELECT * FROM asset_register WHERE request_key=?');$q->execute([$request]);if($existing=$q->fetch()){foreach($data as $key=>$value)if((string)$existing[$key] !==(string)$value)throw new RuntimeException('Anfrageidentität mit abweichender Anlage.');$pdo->commit();return (int)$existing['id'];}$pdo->prepare('INSERT INTO asset_register(name,acquired_on,in_service_on,acquisition_cents,residual_cents,document_id,property_id,notes,request_key) VALUES(?,?,?,?,?,?,?,?,?)')->execute([...array_values($data),$request]);$id=(int)$pdo->lastInsertId();}assetEvent($pdo,$admin,$id,$old?'draft_updated':'draft_created',['previous'=>$old?$old:[],'values'=>$data]);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function assetSetPlan(PDO $pdo,int $admin,int $id,int $year,int $amount,?int $version):void {
 if($year<1900||$year>2200||$amount<0||$amount>99999999999)throw new InvalidArgumentException('Planjahr/Betrag ungültig.');caBegin($pdo,$admin);try{$a=assetLock($pdo,$id,$version);if($a['status']!=='draft')throw new RuntimeException('Geprüfter Plan gesperrt.');if($year<(int)substr($a['in_service_on'],0,4))throw new RuntimeException('Planjahr vor Inbetriebnahme.');$q=$pdo->prepare('SELECT COALESCE(SUM(amount_cents),0) FROM asset_plan_rows WHERE asset_id=? AND year<>?');$q->execute([$id,$year]);if((int)$q->fetchColumn()+$amount>(int)$a['acquisition_cents']-(int)$a['residual_cents'])throw new RuntimeException('Plan überschreitet Anschaffungswert abzüglich Restwert.');if($amount)$pdo->prepare('INSERT INTO asset_plan_rows(asset_id,year,amount_cents) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount_cents=VALUES(amount_cents)')->execute([$id,$year,$amount]);else $pdo->prepare('DELETE FROM asset_plan_rows WHERE asset_id=? AND year=?')->execute([$id,$year]);$pdo->prepare('UPDATE asset_register SET row_version=row_version+1 WHERE id=?')->execute([$id]);assetEvent($pdo,$admin,$id,'plan_draft_changed',['year'=>$year,'amount_cents'=>$amount]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function assetApprove(PDO $pdo,int $admin,int $id,?int $version,string $reference,bool $reviewed):void {
 $reference=caText($reference,500);if(!$reviewed)throw new RuntimeException('Fachliche Prüfung ausdrücklich bestätigen.');caBegin($pdo,$admin);try{$a=assetLock($pdo,$id,$version);if($a['status']!=='draft')throw new RuntimeException('Nur Entwurf freigeben.');assetValidateDocument($pdo,(int)$a['document_id']);$q=$pdo->prepare('SELECT COALESCE(SUM(amount_cents),0) FROM asset_plan_rows WHERE asset_id=?');$q->execute([$id]);if((int)$q->fetchColumn()!==(int)$a['acquisition_cents']-(int)$a['residual_cents'])throw new RuntimeException('Manueller Plan unvollständig. Fachlich festgelegte Jahresbeträge müssen Anschaffungswert minus Restwert ergeben.');$year=(int)substr($a['acquired_on'],0,4);$pdo->prepare('INSERT INTO asset_sequences(year,last_number) VALUES(?,0) ON DUPLICATE KEY UPDATE year=VALUES(year)')->execute([$year]);$q=$pdo->prepare('SELECT last_number FROM asset_sequences WHERE year=? FOR UPDATE');$q->execute([$year]);$next=(int)$q->fetchColumn()+1;$pdo->prepare('UPDATE asset_sequences SET last_number=? WHERE year=?')->execute([$next,$year]);$pdo->prepare("UPDATE asset_register SET status='approved',number=?,review_reference=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP(),row_version=row_version+1 WHERE id=?")->execute([sprintf('A-%04d-%05d',$year,$next),$reference,$admin,$id]);assetEvent($pdo,$admin,$id,'approved',['review_reference'=>$reference]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function assetRetire(PDO $pdo,int $admin,int $id,?int $version,string $date,string $reason):void {
 caDate($date);$reason=caText($reason,500);caBegin($pdo,$admin);try{$a=assetLock($pdo,$id,$version);if($a['status']!=='approved'||$date<$a['in_service_on'])throw new RuntimeException('Geprüfte aktive Anlage und gültiges Abgangsdatum erforderlich.');$pdo->prepare("UPDATE asset_register SET status='retired',retired_on=?,retirement_reason=?,row_version=row_version+1 WHERE id=?")->execute([$date,$reason,$id]);assetEvent($pdo,$admin,$id,'retired',['date'=>$date,'reason'=>$reason]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function assetSchedule(array $asset,array $rows):array {$balance=(int)$asset['acquisition_cents'];$residual=(int)$asset['residual_cents'];usort($rows,fn($a,$b)=>(int)$a['year']<=>(int)$b['year']);$result=[];$years=[];foreach($rows as $r){$year=(int)$r['year'];if(isset($years[$year])||$year<(int)substr($asset['in_service_on'],0,4))throw new RuntimeException('Planjahr doppelt oder vor Inbetriebnahme.');$years[$year]=true;$amount=(int)$r['amount_cents'];if($amount<=0||$balance-$amount<$residual)throw new RuntimeException('Unplausibler Anlagenplan.');$balance-=$amount;$result[]=['year'=>(int)$r['year'],'amount_cents'=>$amount,'remaining_cents'=>$balance];}return ['rows'=>$result,'unplanned_cents'=>$balance-$residual,'planned_remaining_cents'=>$balance];}
function assetRegisterCsv(PDO $pdo):string {
 cashAssetsRequire($pdo);$rows=$pdo->query('SELECT a.id,a.number,a.status,a.name,a.acquired_on,a.in_service_on,a.acquisition_cents,a.residual_cents,a.document_id,p.year,p.amount_cents,a.review_reference,a.retired_on FROM asset_register a LEFT JOIN asset_plan_rows p ON p.asset_id=a.id ORDER BY a.id,p.year LIMIT 10001')->fetchAll();if(count($rows)>10000)throw new RuntimeException('Anlagenexport maximal 10000 Zeilen. Zeitraum-/Archivkonzept erforderlich.');
 $out="\xEF\xBB\xBF".implode(';',array_map('invCsvCell',['Anlage-ID','Nummer','Status','Bezeichnung','Anschaffung','Inbetriebnahme','Anschaffungswert EUR','Restwert EUR','Original-Dokument-ID','Manuelles Planjahr','Manueller Planbetrag EUR','Fachlicher Prüfvermerk','Abgangsdatum']))."\r\n";
 foreach($rows as $r){$r['acquisition_cents']=financeDecimal((int)$r['acquisition_cents']);$r['residual_cents']=financeDecimal((int)$r['residual_cents']);$r['amount_cents']=$r['amount_cents']===null?'':financeDecimal((int)$r['amount_cents']);$out.=implode(';',array_map('invCsvCell',array_values($r)))."\r\n";}return $out;
}
